  ('aded7c74-193e-565e-bd7d-73e5fbf20479', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'medium',
   $q$The merchant was "rich in a product that was literally disappearing beneath his feet." What irony does this phrase capture?$q$, $q$[{"text":"He had sold all of his ice before the first ship even left port.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He owned plenty of ice, yet his supply was melting away as he held it.","is_correct":true},{"text":"He was wealthy from other businesses and did not care about the ice.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"He hid the ice under the floor of his house to keep it safe.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$He owned plenty of ice, yet his supply was melting away as he held it.$q$, $q$Being "rich" in a product clashes with that product melting in the ship's hold, as the paragraph says "much of the cargo melted." The passage does not mention other businesses, so that choice adds unsupported information.$q$, 'draft', 'a64d80fc-e58f-572f-aac4-f572782d3a6c')
